def analyze_patterns(inputs, outputs):
    print("Analyzing patterns:")
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        print(f"Input {i}: '{inp}' -> Output {i}: '{outp}'")

        # Check for character differences
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")

        # Check length differences
        if len(inp) != len(outp):
            print(f"  Length change: {len(inp)} -> {len(outp)}")

inputs = ['dvg', 'aeihej', 'ugjcux', 'wjg', 'hj']
outputs = ['dvug', 'aeihej', 'ajcux', 'wjug', 'hj']
analyze_patterns(inputs, outputs)

